def compute(vars):
    gain = vars["v1"]
    proceeds = vars["v2"]
    if proceeds == 0:
        return None

    ratio = gain / proceeds
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "gain_to_proceeds_ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
